package com.javasmyths.highguard;
import java.nio.file.*;import java.time.Instant;import java.util.*;import java.io.*;
import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.stereotype.Component;import org.springframework.beans.factory.annotation.Value;
@Component public class ShipStore {
 public static class Saved {public int schemaVersion=1;public String ruleset="CT-HG1980",savedAt;public Design design;}
 private final Path directory,book2;private final ObjectMapper mapper=new ObjectMapper();
 public ShipStore(@Value("${highguard.storage-dir}")String dir,@Value("${highguard.book2-dir}")String old){directory=Paths.get(dir).toAbsolutePath().normalize();book2=Paths.get(old).toAbsolutePath().normalize();if(directory.equals(book2)||directory.startsWith(book2)||book2.startsWith(directory))throw new IllegalArgumentException("Book 2 and High Guard need separate storage directories.");}
 private Path path(String id){if(id==null||!id.matches("[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}"))throw new IllegalArgumentException("Invalid ship identifier.");return directory.resolve(id+".json");}
 public synchronized Saved read(String id)throws IOException{Path p=path(id);if(Files.size(p)>1000000)throw new IOException("Ship file is too large.");Saved s=mapper.readValue(p.toFile(),Saved.class);if(s.schemaVersion!=1||!"CT-HG1980".equals(s.ruleset)||s.design==null||!id.equals(s.design.id))throw new IOException("Unsupported High Guard file.");return s;}
 public synchronized Saved save(Design d)throws IOException{if(d.id==null||d.id.isEmpty())d.id=UUID.randomUUID().toString();else read(d.id);Files.createDirectories(directory);Path target=path(d.id),temp=Files.createTempFile(directory,".save-",".tmp");Saved s=new Saved();s.design=d;s.savedAt=Instant.now().toString();try{mapper.writerWithDefaultPrettyPrinter().writeValue(temp.toFile(),s);try(java.nio.channels.FileChannel channel=java.nio.channels.FileChannel.open(temp,StandardOpenOption.WRITE)){channel.force(true);}try{Files.move(temp,target,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(temp,target,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temp);}return s;}
 public synchronized List<Saved> list()throws IOException{List<Saved> all=new ArrayList<>();if(Files.isDirectory(directory))try(java.util.stream.Stream<Path> files=Files.list(directory)){for(Path p:(Iterable<Path>)files.filter(x->x.getFileName().toString().matches("[a-f0-9-]{36}\\.json"))::iterator){String n=p.getFileName().toString();all.add(read(n.substring(0,36)));}}all.sort(Comparator.comparing((Saved s)->s.savedAt).reversed());return all;}
 public List<Map<String,String>> book2List()throws IOException{List<Map<String,String>> result=new ArrayList<>();if(Files.isDirectory(book2))try(java.util.stream.Stream<Path> files=Files.list(book2)){for(Path p:(Iterable<Path>)files.filter(x->x.getFileName().toString().matches("[a-f0-9-]{36}\\.json"))::iterator){if(Files.size(p)>1000000||Files.isSymbolicLink(p))continue;com.fasterxml.jackson.databind.JsonNode node=mapper.readTree(p.toFile());if(node.path("design").isObject()){Map<String,String> m=new LinkedHashMap<>();m.put("id",p.getFileName().toString().replace(".json",""));m.put("name",node.path("design").path("name").asText("Book 2 ship"));result.add(m);}}}return result;}
 public byte[] book2Read(String id)throws IOException{path(id);Path p=book2.resolve(id+".json");if(Files.isSymbolicLink(p)||Files.size(p)>1000000)throw new IOException("Unsupported source file.");return Files.readAllBytes(p);}
 public byte[] export(String id)throws IOException{return mapper.writerWithDefaultPrettyPrinter().writeValueAsBytes(read(id));}
}
